import re

text = open("guides/source/active_record_validations.md").read()
lines = text.split("\n")

escaped = r'\\/`*_{}[]()#+-.!:,;|&<>^~=\'\"'
def dom_id_text(t):
    t = t.lower().replace("?", "-questionmark").replace("!", "-bang")
    t = re.sub(r'[%s]+' % escaped, " ", t)
    return t.strip().replace(" ", "-")

headings = []
in_fence = False
prev_nonblank = None
for line in lines:
    if line.startswith("```"):
        in_fence = not in_fence
        prev_nonblank = line
        continue
    if in_fence:
        prev_nonblank = line
        continue
    if re.match(r'^-{4,}\s*$', line):
        if prev_nonblank is not None and not re.match(r'^#', prev_nonblank) and prev_nonblank.strip():
            headings.append((2, prev_nonblank))
        prev_nonblank = None
        continue
    m = re.match(r'^(#{1,5}) (.+)$', line)
    if m:
        headings.append((len(m.group(1)), m.group(2)))
    prev_nonblank = line

node_ids = {}
ids = []
hier = []
for (level, htext) in headings:
    while hier and hier[-1][0] >= level:
        hier.pop()
    parent = hier[-1][1] if hier else None
    raw = dom_id_text(htext)
    if raw in node_ids:
        entry = node_ids[raw]
        if len(entry) > 1:
            dups = node_ids.pop(raw)
            new_id = dups[-2] + "-" + raw
            dups[-1]["id"] = new_id
            node_ids[new_id] = dups
        dom = (parent + "-" + raw) if parent else raw
    else:
        dom = raw
    node = {"id": dom, "text": htext}
    node_ids[dom] = hier + [node]
    ids.append(dom)
    hier = hier + [(level, dom)]

anchors = set(ids)

links = set()
in_fence = False
for line in lines:
    if line.startswith("```"):
        in_fence = not in_fence
        continue
    if in_fence:
        continue
    for m in re.finditer(r'\]\((#[^)\s]+)\)', line):
        links.add(m.group(1))

ok = True
for l in sorted(links):
    if l[1:] in anchors:
        print(f"  OK   {l}")
    else:
        ok = False
        print(f"  FAIL {l}")
print("ALL INTERNAL LINKS RESOLVE" if ok else "SOME INTERNAL LINKS MISSING")

print()
for (level, htext), dom in zip(headings, ids):
    if htext in ("Validation Triggers", "Custom Contexts", "Alternate Ways to Validate",
                 "`errors.add`", "`errors.where` and Error Object", "`absence`", "`presence`"):
        print(f"  #{dom}")
EOF

